import express from 'express';

const PENGGUNA = { 'kunci-kasir': { nama: 'Rina', peran: 'kasir' }, 'kunci-admin': { nama: 'Sari', peran: 'admin' } };
function kenali(req, res, next) {
  const p = PENGGUNA[req.get('x-api-key')];
  if (!p) return res.status(401).json({ error: 'Kunci API salah atau tidak ada' });
  req.pengguna = p;
  next();
}
function butuhPeran(peran) {
  return (req, res, next) => {
    if (req.pengguna.peran !== peran) return res.status(403).json({ error: `Khusus ${peran}` });
    next();
  };
}
const app = express();
app.get('/menu', (req, res) => res.json(['Kopi']));
app.get('/laporan', kenali, (req, res) => res.json({ untuk: req.pengguna.nama }));
app.delete('/menu/:id', kenali, butuhPeran('admin'), (req, res) => res.sendStatus(204));
const server = app.listen(3000);

const coba = async (method, jalur, kunci) => {
  const r = await fetch('http://localhost:3000' + jalur, { method, headers: kunci ? { 'X-API-Key': kunci } : {} });
  console.log(method, jalur, kunci ?? '-', r.status);
};
await coba('GET', '/menu');
await coba('GET', '/laporan');
await coba('GET', '/laporan', 'kunci-kasir');
await coba('DELETE', '/menu/1', 'kunci-kasir');
await coba('DELETE', '/menu/1', 'kunci-admin');
server.close();

