import express from 'express';
const app = express();
app.use(express.json());
app.get('/menu', (req, res) => res.json(['Kopi']));
app.post('/menu', (req, res) => res.status(201).json({ nama: req.body.nama }));
const server = app.listen(3000);
const r = await fetch('http://localhost:3000/menu', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ nama: 'Teh' }) });
console.log(r.status);
server.close();

import express from 'express';
function butuhKunci(req, res, next) {
  if (req.get('x-api-key') !== 'rahasia-dapur') return res.status(401).json({ error: 'Kunci salah' });
  next();
}
const app = express();
app.use(express.json());
app.get('/menu', (req, res) => res.json(['Kopi']));
app.post('/menu', butuhKunci, (req, res) => res.status(201).json({ nama: req.body.nama }));
const server = app.listen(3000);
for (const kunci of [undefined, 'rahasia-dapur']) {
  const headers = { 'Content-Type': 'application/json' };
  if (kunci) headers['X-API-Key'] = kunci;
  const r = await fetch('http://localhost:3000/menu', { method: 'POST', headers, body: JSON.stringify({ nama: 'Teh' }) });
  console.log(r.status);
}
server.close();

