import express from 'express';
const app = express();
function minimalUmur(n) {
  return (req, res, next) => {
    if (Number(req.query.umur) < n) return res.sendStatus(403);
    next();
  };
}
app.get('/film', minimalUmur(17), (req, res) => res.send('boleh'));
const server = app.listen(3000);
const a = await fetch('http://localhost:3000/film?umur=15');
const b = await fetch('http://localhost:3000/film?umur=20');
console.log(a.status, b.status);
server.close();
